```python
from typing import List, Dict, Any

def process(data: List[Dict[str, Any]], threshold: float) -> List[Dict[str, Any]]:
    try:
        return [
            item for item in data
            if item['score'] > threshold and item.get('active', False)
        ]
    except (KeyError, AttributeError) as e:
        raise ValueError("Invalid data structure: missing 'score' or non-iterable input") from e
```

